 51	  async function refresh(message?: string) {
 52	    await queryClient.invalidateQueries({ queryKey: applicationQueryKeys.all });
 53	    if (message) setStatus(message);
 54	  }
 55	
 56	  async function onDeleted() {
 57	    await navigate({ to: "/admin/applications" });
 58	  }
 59	
 60	  function navigateToTab(tab: ApplicationTab) {
 61	    switch (tab) {
 62	      case "overview":
 63	        return navigate({
 64	          params: { applicationId },
 65	          to: "/admin/applications/$applicationId",
 66	        });
 67	      case "settings":
 68	        return navigate({
 69	          params: { applicationId },
 70	          to: "/admin/applications/$applicationId/settings",
 71	        });
 72	      case "roles":
 73	        return navigate({
 74	          params: { applicationId },
 75	          to: "/admin/applications/$applicationId/roles",
 76	        });
 77	      case "oidc":
 78	        return navigate({
 79	          params: { applicationId },
 80	          to: "/admin/applications/$applicationId/oidc",
 81	        });
 82	      case "access":
 83	        return navigate({
 84	          params: { applicationId },
 85	          to: "/admin/applications/$applicationId/access",
 86	        });
 87	    }
 88	  }
 89	
 90	  return (
 91	    <AdminLayout
 92	      activePath="/admin/applications"
 93	      breadcrumbLabel={application?.name ?? "Application detail"}
 94	      description={
 95	        application
 96	          ? `Manage ${application.name}'s authorization boundary and connected clients.`
 97	          : "Review the selected application's authorization settings."
 98	      }
 99	      eyebrow="Authorization / Application detail"
100	      title={application?.name ?? "Application detail"}
101	    >
102	      <div className="space-y-6">
103	        {applicationsQuery.isLoading ? <AdminStatus>Loading application...</AdminStatus> : null}
104	        {applicationsQuery.isError ? (
105	          <AdminError>{formatApiError(applicationsQuery.error)}</AdminError>
106	        ) : null}
107	        {!applicationsQuery.isLoading && !applicationsQuery.isError && !application ? (
108	          <div className="space-y-4">
109	            <AdminError>The application is no longer available.</AdminError>
110	            <LinkButton href="/admin/applications" variant="secondary">
111	              Back to applications
112	            </LinkButton>
113	          </div>
114	        ) : null}
115	        {application ? (
116	          <ApplicationDetailContext.Provider value={{ application, onDeleted, onRefresh: refresh }}>
117	            <section aria-labelledby="application-detail-title" className="space-y-6">
118	              <div className="flex flex-wrap items-end justify-between gap-4">
119	                <div>
120	                  <LinkButton className="mb-4" href="/admin/applications" variant="ghost">
121	                    Back to applications
122	                  </LinkButton>
123	                  <p className="text-sm font-medium uppercase tracking-[0.16em] text-(--tangerine)">
124	                    Application detail
125	                  </p>
126	                  <h2
127	                    className="mt-2 font-display text-3xl font-semibold text-kumo-strong"
128	                    id="application-detail-title"
129	                  >
130	                    {application.name}
131	                  </h2>
132	                </div>
133	                <div className="flex items-center gap-3">
134	                  <StatusPill status={application.status} />
135	                  <Badge appearance="filled" variant="neutral">
136	                    authz version {application.authzVersion}
137	                  </Badge>
138	                </div>
139	              </div>
140	              <Tabs
141	                className="w-full"
142	                onValueChange={(value) => {
143	                  if (isApplicationTab(value)) void navigateToTab(value);
144	                }}
145	                tabs={applicationTabItems}
146	                value={activeTab}
147	                variant="underline"
148	              />
149	              {status ? <AdminStatus>{status}</AdminStatus> : null}
150	              {children}
151	            </section>
152	          </ApplicationDetailContext.Provider>
153	        ) : null}
154	      </div>
155	    </AdminLayout>
156	  );
157	}
