159	export function useApplicationDetail() {
160	  const context = useContext(ApplicationDetailContext);
161	  if (!context) {
162	    throw new Error("Application detail tabs must render inside ApplicationDetailPage.");
163	  }
164	  return context;
165	}
166	
167	function applicationTabFromPath(pathname: string): ApplicationTab {
168	  if (pathname.endsWith("/settings")) return "settings";
169	  if (pathname.endsWith("/roles")) return "roles";
170	  if (pathname.endsWith("/oidc") || pathname.includes("/oidc/")) return "oidc";
171	  if (pathname.endsWith("/access")) return "access";
172	  return "overview";
173	}
174	
175	function isApplicationTab(value: string): value is ApplicationTab {
176	  return applicationTabItems.some((tab) => tab.value === value);
177	}

